#!/usr/bin/env bash
# Copy the installed Antigravity plugin into each T3 Antigravity profile.
set -eu
python3 - "$HOME" <<'PY'
import hashlib
import json
import os
from pathlib import Path
import shutil
import sys
import tempfile

home = Path(sys.argv[1])
src = home / '.gemini/config/plugins/viz-os/skills'
names = ('class', 'deck', 'sketch')
for name in names:
    if not (src / name / 'SKILL.md').is_file():
        sys.exit(f'Missing installed skill: {src / name}')

# Ignore Python's generated bytecode in both ownership checks and copies.
def generated(path):
    return any(part == '__pycache__' or part.endswith(('.pyc', '.pyo'))
               for part in path.parts)

# Refuse to overwrite an edited or independently created skill.
def digest(root):
    h = hashlib.sha256()
    for p in sorted(root.rglob('*')):
        if generated(p.relative_to(root)):
            continue
        if p.is_symlink():
            raise ValueError(f'Symlink in managed skill: {p}')
        h.update(str(p.relative_to(root)).encode() + b'\0')
        if p.is_file():
            h.update(p.read_bytes())
    return h.hexdigest()

profiles = home / '.t3/userdata/providers/antigravity'
count = 0
for profile in sorted(profiles.glob('*')):
    if not profile.is_dir():
        continue
    parent = profile / 'antigravity-cli'
    if not parent.is_dir() or parent.is_symlink():
        raise SystemExit(f'Unsafe or missing profile directory: {parent}')
    dest = parent / 'skills'
    marker = dest / '.viz-os-install.json'
    old = json.loads(marker.read_text()) if marker.is_file() else {}
    for name in names:
        target = dest / name
        if target.exists() or target.is_symlink():
            if target.is_symlink() or not target.is_dir() or old.get(name) != digest(target):
                raise SystemExit(f'Refusing to overwrite unowned or changed skill: {target}')
    # Snapshot shared entries inside the profile, then replace only the link.
    if dest.is_symlink():
        if not dest.is_dir():
            raise SystemExit(f'Broken skills link: {dest}')
        with tempfile.TemporaryDirectory(prefix='.viz-os-', dir=parent) as tmp:
            staged = Path(tmp) / 'skills'
            shutil.copytree(dest, staged, symlinks=False)
            link = os.readlink(dest)
            dest.unlink()
            try:
                os.rename(staged, dest)
            except BaseException:
                dest.symlink_to(link)
                raise
    elif not dest.exists():
        dest.mkdir()
    elif not dest.is_dir():
        raise SystemExit(f'Not a skills directory: {dest}')
    # Copy first; rename old managed trees to a temporary backup until success.
    with tempfile.TemporaryDirectory(prefix='.viz-os-', dir=parent) as tmp:
        tmp = Path(tmp)
        for name in names:
            shutil.copytree(src / name, tmp / name, symlinks=False,
                            ignore=shutil.ignore_patterns('__pycache__', '*.pyc', '*.pyo'))
        new = {name: digest(tmp / name) for name in names}
        moved, installed = [], []
        try:
            for name in names:
                target = dest / name
                if target.exists():
                    os.rename(target, tmp / (name + '.old'))
                    moved.append(name)
                os.rename(tmp / name, target)
                installed.append(name)
            temp_marker = tmp / 'marker'
            temp_marker.write_text(json.dumps(new, indent=2) + '\n')
            os.replace(temp_marker, marker)
        except BaseException:
            for name in installed:
                shutil.rmtree(dest / name)
            for name in moved:
                os.rename(tmp / (name + '.old'), dest / name)
            raise
    count += 1
if not count:
    sys.exit('No T3 Antigravity profiles found; nothing installed')
print(f'viz-os skills copied into {count} T3 Antigravity profile(s)')
PY
